"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { ConfirmDialog } from "@/components/ui/confirm-dialog"

interface List {
  id: number
  name: string
  slug: string
  bg_image_url: string
  created_at: string
  contact_count: number
}

interface Contact {
  id: number
  email: string
  name: string
  topic: string
  status: string
}

export default function Lists() {
  const [lists, setLists] = useState<List[]>([])
  const [contacts, setContacts] = useState<Contact[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [newList, setNewList] = useState({ name: "", slug: "", bg_image_url: "" })
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean; list: List | null }>({ open: false, list: null })
  const router = useRouter()

  useEffect(() => {
    loadLists()
    loadContacts()
  }, [])

  const loadLists = async () => {
    try {
      const token = localStorage.getItem("auth_token")
      
      if (!token) {
        router.push("/")
        return
      }

      const response = await fetch("/api/lists", {
        headers: { "Authorization": `Bearer ${token}` }
      })
      
      if (response.ok) {
        const data = await response.json()
        setLists(data.lists || [])
      }
    } catch (error) {
      console.error("Error loading lists:", error)
    }
  }

  const loadContacts = async () => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/contacts/", {
        headers: { "Authorization": `Bearer ${token}` }
      })
      
      if (response.ok) {
        const data = await response.json()
        setContacts(data.contacts || [])
      }
    } catch (error) {
      console.error("Error loading contacts:", error)
    } finally {
      setLoading(false)
    }
  }

  const handleCreateList = async (e: React.FormEvent) => {
    e.preventDefault()
    
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/lists", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(newList)
      })

      if (response.ok) {
        setNewList({ name: "", slug: "", bg_image_url: "" })
        setShowCreateForm(false)
        loadLists()
      }
    } catch (error) {
      console.error("Error creating list:", error)
    }
  }

  const handleEditList = async (listId: number, updatedData: { name: string; bg_image_url: string }) => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch(`/api/lists/${listId}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(updatedData)
      })

      if (response.ok) {
        loadLists()
        setEditingList(null)
      }
    } catch (error) {
      console.error("Error updating list:", error)
    }
  }

  const handleDeleteList = async (listId: number) => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch(`/api/lists/${listId}`, {
        method: "DELETE",
        headers: {
          "Authorization": `Bearer ${token}`
        }
      })

      if (response.ok) {
        loadLists()
      }
    } catch (error) {
      console.error("Error deleting list:", error)
    }
  }

  const confirmDeleteList = (list: List) => {
    setDeleteConfirm({ open: true, list })
  }

  const generateSlug = (name: string) => {
    return name
      .toLowerCase()
      .replace(/[^a-z0-9 -]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim('-')
  }

  const handleNameChange = (name: string) => {
    setNewList({ 
      ...newList, 
      name, 
      slug: generateSlug(name) 
    })
  }

  const handleAddContactToList = async (contactId: number, listId: number) => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/contacts/add-to-list", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({ contact_id: contactId, list_id: listId })
      })

      if (response.ok) {
        loadLists()
      }
    } catch (error) {
      console.error("Error adding contact to list:", error)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando listas...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <Button variant="ghost" onClick={() => router.push("/dashboard")}>
                ← Dashboard
              </Button>
              <h1 className="text-2xl font-bold text-gray-900">Listas de Difusión</h1>
            </div>
            <Button onClick={() => setShowCreateForm(!showCreateForm)}>
              Crear Lista
            </Button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Create List Form */}
          {showCreateForm && (
            <Card>
              <CardHeader>
                <CardTitle>Crear Nueva Lista</CardTitle>
                <CardDescription>
                  Crea una nueva lista de difusión
                </CardDescription>
              </CardHeader>
              <CardContent>
                <form onSubmit={handleCreateList} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="name">Nombre de la Lista *</Label>
                    <Input
                      id="name"
                      type="text"
                      placeholder="Ej: Clases Heels"
                      value={newList.name}
                      onChange={(e) => handleNameChange(e.target.value)}
                      required
                    />
                  </div>
                  
                  <div className="space-y-2">
                    <Label htmlFor="slug">Slug (URL) *</Label>
                    <Input
                      id="slug"
                      type="text"
                      placeholder="clases-heels"
                      value={newList.slug}
                      onChange={(e) => setNewList({ ...newList, slug: e.target.value })}
                      required
                    />
                    <p className="text-xs text-gray-500">
                      URL pública: /subscribe/{newList.slug}
                    </p>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="bg_image">Imagen de Fondo (URL)</Label>
                    <Input
                      id="bg_image"
                      type="url"
                      placeholder="https://ejemplo.com/imagen.jpg"
                      value={newList.bg_image_url}
                      onChange={(e) => setNewList({ ...newList, bg_image_url: e.target.value })}
                    />
                  </div>

                  <div className="flex space-x-2">
                    <Button type="submit" className="flex-1">
                      Crear Lista
                    </Button>
                    <Button 
                      type="button" 
                      variant="outline" 
                      onClick={() => setShowCreateForm(false)}
                    >
                      Cancelar
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* Edit List Form */}
          {editingList && (
            <Card>
              <CardHeader>
                <CardTitle>Editar Lista</CardTitle>
                <CardDescription>
                  Modifica los datos de tu lista
                </CardDescription>
              </CardHeader>
              <CardContent>
                <form onSubmit={(e) => {
                  e.preventDefault()
                  handleEditList(editingList.id, {
                    name: editingList.name,
                    bg_image_url: editingList.bg_image_url || ""
                  })
                }}>
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="edit_name">Nombre de la Lista *</Label>
                      <Input
                        id="edit_name"
                        type="text"
                        placeholder="Ej: Clases Heels"
                        value={editingList.name}
                        onChange={(e) => setEditingList({ ...editingList, name: e.target.value })}
                        required
                      />
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="edit_slug">Slug (URL) *</Label>
                      <Input
                        id="edit_slug"
                        type="text"
                        value={editingList.slug}
                        disabled
                        className="bg-gray-100"
                      />
                      <p className="text-xs text-gray-500">
                        El slug no se puede cambiar después de crear la lista
                      </p>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="edit_bg_image">Imagen de Fondo (URL)</Label>
                      <Input
                        id="edit_bg_image"
                        type="url"
                        placeholder="https://ejemplo.com/imagen.jpg"
                        value={editingList.bg_image_url || ""}
                        onChange={(e) => setEditingList({ ...editingList, bg_image_url: e.target.value })}
                      />
                    </div>

                    <div className="flex space-x-2">
                      <Button type="submit" className="flex-1">
                        Guardar Cambios
                      </Button>
                      <Button 
                        type="button" 
                        variant="outline" 
                        onClick={() => setEditingList(null)}
                      >
                        Cancelar
                      </Button>
                    </div>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* Lists */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <CardTitle>Listas de Difusión ({lists.length})</CardTitle>
                <CardDescription>
                  Gestiona tus listas de suscriptores
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {lists.length === 0 ? (
                    <p className="text-gray-500 text-center py-8">
                      No hay listas creadas
                    </p>
                  ) : (
                    lists.map((list) => (
                      <div key={list.id} className="flex items-center justify-between p-4 border rounded-lg">
                        <div className="flex-1">
                          <div className="flex items-center space-x-3">
                            <h3 className="font-medium">{list.name}</h3>
                            <Badge variant="secondary">
                              {list.contact_count} contactos
                            </Badge>
                          </div>
                          <p className="text-sm text-gray-600">
                            Slug: {list.slug}
                          </p>
                          <p className="text-sm text-gray-500">
                            URL: /subscribe/{list.slug}
                          </p>
                          <p className="text-xs text-gray-400">
                            Creada: {new Date(list.created_at).toLocaleDateString()}
                          </p>
                        </div>
                        <div className="flex space-x-2">
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => setSelectedList(list)}
                          >
                            Gestionar
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => setEditingList(list)}
                          >
                            Editar
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => confirmDeleteList(list)}
                          >
                            Eliminar
                          </Button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Contact Management Modal */}
        {selectedList && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <Card className="w-full max-w-2xl max-h-[80vh] overflow-y-auto">
              <CardHeader>
                <div className="flex justify-between items-center">
                  <div>
                    <CardTitle>Gestionar: {selectedList.name}</CardTitle>
                    <CardDescription>
                      Asocia contactos a esta lista
                    </CardDescription>
                  </div>
                  <Button 
                    variant="ghost" 
                    onClick={() => setSelectedList(null)}
                  >
                    ✕
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <h4 className="font-medium">Contactos Disponibles</h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto">
                    {contacts.map((contact) => (
                      <div key={contact.id} className="flex items-center justify-between p-3 border rounded">
                        <div>
                          <p className="font-medium">{contact.email}</p>
                          {contact.name && (
                            <p className="text-sm text-gray-600">{contact.name}</p>
                          )}
                        </div>
                        <Button 
                          size="sm"
                          onClick={() => handleAddContactToList(contact.id, selectedList.id)}
                        >
                          Agregar
                        </Button>
                      </div>
                    ))}
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        )}
      </main>
    </div>
  )
}
